// How the app writes a number of todos (Linh, UX): a dot every three digits from 1,000 up, in every sentence, including the
// open-todo count line. Below 1,000 nothing changes. Years and dates are not counts. Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const backup = require('../app/backup.js');
const { MESSAGES, formatCount, fill, confirmText, backupFileName } = backup;

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

test('formatCount: unchanged below 1,000, a dot every three digits from 1,000 up', () => {
  for (const [n, s] of [[0, '0'], [1, '1'], [12, '12'], [999, '999'], [1000, '1.000'], [2001, '2.001'], [12500, '12.500'],
    [999999, '999.999'], [1000000, '1.000.000']]) {
    assert.equal(formatCount(n), s, `${n}`);
  }
});

test('every sentence with a count uses the dot', () => {
  assert.equal(fill(MESSAGES.backedUp, { n: 1000 }), 'Đã sao lưu 1.000 việc.');
  assert.equal(fill(MESSAGES.imported, { n: 12500 }), 'Đã nhập 12.500 việc.');
  assert.equal(fill(MESSAGES.backedUp, { n: 999 }), 'Đã sao lưu 999 việc.');
  assert.equal(confirmText({ readError: false, current: 2001, incoming: 1000 }), 'Thay 2.001 việc hiện có bằng 1.000 việc trong file?');
  assert.equal(confirmText({ readError: true, current: 0, incoming: 1500 }),
    'Thay danh sách đã lưu không đọc được bằng 1.500 việc trong file?');
  assert.equal(confirmText({ readError: true, current: 1234, incoming: 5678 }),
    'Thay danh sách đã lưu không đọc được và 1.234 việc bạn vừa thêm (chưa lưu) bằng 5.678 việc trong file?');
});

test('a date is not a count: the backup file name keeps the year as 2026', () => {
  assert.equal(backupFileName(new Date(2026, 9, 29)), 'todo-sao-luu-2026-10-29.json');
});

function countLine(openCount, doneCount) {
  const todos = [];
  for (let i = 0; i < openCount + doneCount; i++) todos.push({ id: `id-${i}`, title: `Việc ${i}`, done: i >= openCount, createdAt: 1 });
  const elements = {};
  const fakeElement = () => {
    const el = { textContent: '', innerHTML: '', hidden: false, dataset: {}, children: {}, append() {} };
    el.querySelector = (sel) => (el.children[sel] ||= fakeElement());
    return el;
  };
  const store = { readError: false, load: () => ({ todos, readError: false }), save: () => 'saved', replace: () => 'saved' };
  const document = {
    querySelector: (sel) => (elements[sel] ||= fakeElement()),
    querySelectorAll: () => [],
    createElement: fakeElement,
  };
  vm.runInNewContext(appJs, { ...backup, store, document });
  return elements['#count'].textContent;
}

test('the open-todo count line uses the dot from 1,000 up', () => {
  assert.equal(countLine(999, 5), '999 việc chưa xong');
  assert.equal(countLine(1000, 0), '1.000 việc chưa xong');
  assert.equal(countLine(2001, 3), '2.001 việc chưa xong');
});

